/// <summary>
/// Packs an extension table record to the container field <C>PackedExtensions</C>.
/// </summary>
/// <param name="_METPurchTable">
/// The extension table record.
/// </param>
public void packMETPurchTable(METPurchTable _METPurchTable)
{
    _METPurchTable.PurchTable = this.RecId;
    this.SysExtensionSerializerMap::packExtensionTable(_METPurchTable);
}

    /// <summary>
    /// To fetch field value of vendor site settup
    /// </summary>
    /// <param name = "_fieldnum"> Field number to ident the field</param>
    /// <returns>anytype value</returns>
    public anytype getVendSiteSettingsSetupFieldValues(FieldId _fieldnum)
    {
        METVendSiteSettingsSetup METVendSiteSettingsSetup;

        select firstonly1 METVendSiteSettingsSetup Order by Level desc
            where METVendSiteSettingsSetup.AssignedVendorAccount == this.OrderAccount
            &&  ((METVendSiteSettingsSetup.AssignedSite == this.InventSiteId
            && METVendSiteSettingsSetup.AssignedWH == this.InventLocationId)
            || (METVendSiteSettingsSetup.Level == 1
            &&  METVendSiteSettingsSetup.AssignedSite == this.InventSiteId)
            || METVendSiteSettingsSetup.Level == 0)
            && METVendSiteSettingsSetup.(_fieldnum);

        return METVendSiteSettingsSetup.(_fieldnum);
    }

    /// <summary>
    /// To fetch EDI address or Email value from vendor site setup based on Send method
    /// </summary>
    /// <returns>EDI address or Email value</returns>
    public LogisticsAddressing getVendSiteSettingsSetupEmailEDI()
    {
        METVendSiteSettingsSetup METVendSiteSettingsSetup;
        LogisticsAddressing EDIEmailAddress;

        select firstonly1 METVendSiteSettingsSetup Order by Level desc
            where METVendSiteSettingsSetup.AssignedVendorAccount == this.OrderAccount
            &&  ((METVendSiteSettingsSetup.AssignedSite == this.InventSiteId
            && METVendSiteSettingsSetup.AssignedWH == this.InventLocationId)
            || (METVendSiteSettingsSetup.Level == 1
            &&  METVendSiteSettingsSetup.AssignedSite == this.InventSiteId)
            || METVendSiteSettingsSetup.Level == 0)
            && METVendSiteSettingsSetup.POSubMode;
        if(METVendSiteSettingsSetup.POSubMode == METConstants::Email)
        {
            EDIEmailAddress =  METVendSiteSettingsSetup.POEmailAddresses;;
        }
        else if(METVendSiteSettingsSetup.POSubMode == METConstants::EDI)
        {
            EDIEmailAddress =  METVendSiteSettingsSetup.POEDIAddressIHG;
        }
        else
        {
            EDIEmailAddress = METConstants::emptyString;
        }
        return EDIEmailAddress;
    }
